/*
 * Zigbee Controller — Board 1
 * Sends LED ON/OFF commands when button on D4 is pressed
 * Green LED on D2 indicates command sent
 */

#include <Zigbee.h>

// LED Driver address
uint16_t ledDriverAddr = 0x0001;

// Command bytes
#define CMD_LED_ON  0x01
#define CMD_LED_OFF 0x00
#define CMD_ACK     0xAA

int lastButtonState = HIGH;
bool ledState = false;

// Callback when ACK received
void onDataReceived(uint8_t *data, int len) {
  if (data[0] == CMD_ACK) {
    Serial.println("[Controller] ACK received from LED Driver!");
    // Blink green LED to confirm
    digitalWrite(2, HIGH);
    delay(100);
    digitalWrite(2, LOW);
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);
  pinMode(4, INPUT_PULLUP);

  // Initialize Zigbee
  Zigbee.begin(11, 0x1234);
  Zigbee.onReceive(onDataReceived);

  Serial.println("[Controller] Zigbee LED Control ready!");
  Serial.print("[Controller] Address: 0x");
  Serial.println(Zigbee.getNodeAddress(), HEX);
  Serial.println("[Controller] Press button on D4 to toggle remote LED\n");
}

void loop() {
  // Read button state
  int buttonState = digitalRead(4);

  // Detect falling edge (button press)
  if (lastButtonState == HIGH && buttonState == LOW) {
    delay(50); // Debounce
    buttonState = digitalRead(4);
    if (buttonState == LOW) {
      ledState = !ledState;
      uint8_t cmd = ledState ? CMD_LED_ON : CMD_LED_OFF;

      // Send command to LED Driver
      Zigbee.send(ledDriverAddr, &cmd, 1);

      Serial.print("[Controller] Sent CMD_");
      Serial.println(ledState ? "ON" : "OFF");

      // Blink green LED
      digitalWrite(2, HIGH);
      delay(100);
      digitalWrite(2, LOW);
    }
  }
  lastButtonState = buttonState;
  delay(10);
}

