/*
 * Zigbee LED Driver — Board 2
 * Receives ON/OFF commands and toggles yellow LED
 * Sends ACK back to Controller
 */

#include <Zigbee.h>

// Controller address
uint16_t controllerAddr = 0x0000;

// Command bytes
#define CMD_LED_ON  0x01
#define CMD_LED_OFF 0x00
#define CMD_ACK     0xAA

bool yellowLedState = false;

// Callback when command received
void onDataReceived(uint8_t *data, int len) {
  if (len < 1) return;

  if (data[0] == CMD_LED_ON) {
    yellowLedState = true;
    digitalWrite(2, HIGH);
    Serial.println("[LED Driver] LED ON");
  } else if (data[0] == CMD_LED_OFF) {
    yellowLedState = false;
    digitalWrite(2, LOW);
    Serial.println("[LED Driver] LED OFF");
  }

  // Send ACK back to Controller
  uint8_t ack = CMD_ACK;
  Zigbee.send(controllerAddr, &ack, 1);
  Serial.println("[LED Driver] ACK sent");
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

  // Initialize Zigbee
  Zigbee.begin(11, 0x1234);
  Zigbee.onReceive(onDataReceived);

  Serial.println("[LED Driver] Zigbee LED Driver ready!");
  Serial.print("[LED Driver] Address: 0x");
  Serial.println(Zigbee.getNodeAddress(), HEX);
  Serial.println("[LED Driver] Waiting for commands...\n");
}

void loop() {
  delay(100);
}
